// Helper function: find last occurrence of sep in s (like str.rfind)
fn str_rfind(s: &str, sep: &str) -> Option<usize> {
    // naive implementation - check all indices from end
    let sep_len = sep.len();
    if sep_len == 0 {
        return None;
    }
    if s.len() < sep_len {
        return None;
    }
    let mut i = s.len() - sep_len;
    loop {
        if &s[i..i + sep_len] == sep {
            return Some(i);
        }
        if i == 0 {
            break;
        }
        i -= 1;
    }
    None
}

